<?php
// Run: php tests/mcp_integration_tools_test.php
//
// The integration MCP tools (orbitra_get_integration_code,
// orbitra_list_app_configs / orbitra_save_app_config,
// orbitra_telegram_status, orbitra_integrations_status) over the real
// mcp.php HTTP endpoint, against the real api.php actions.
//
// The part worth pinning: the code that comes back must be the SAME code the
// panel shows — generated by the PHP mirror of utils/integrationSnippets.js,
// with the campaign's https domain, token and id substituted. A regression
// here is exactly the "MCP and panel ship different code" failure that broke
// the Back Button trap once.

require_once __DIR__ . '/lib/http.php';
date_default_timezone_set('UTC');

$failures = 0;
function check($condition, string $label): void
{
    global $failures;
    echo ($condition ? 'PASS: ' : 'FAIL: ') . $label . "\n";
    if (!$condition) {
        $failures++;
    }
}
function debugDump(string $label, $value): void
{
    if (getenv('MCP_TEST_DEBUG')) {
        fwrite(STDERR, "DEBUG $label: " . var_export($value, true) . "\n");
    }
}

$harness = new OrbitraTestHarness(dirname(__DIR__));
$harness->useProductionRouter();
$harness->start();
$server = null;

try {
    $harness->get('/nonexistent-boot-probe');
    $pdo = $harness->getPdo();
    $dir = $harness->getWorkingDir();

    copy(dirname(__DIR__) . '/mcp.php', $dir . '/mcp.php');
    mkdir($dir . '/mcp');
    copy(dirname(__DIR__) . '/mcp/tools.json', $dir . '/mcp/tools.json');
    mkdir($dir . '/cli');
    copy(dirname(__DIR__) . '/cli/api_invoke.php', $dir . '/cli/api_invoke.php');

    $pdo->exec("INSERT INTO users (id, username, password, role, is_active) VALUES
        (1, 'int_admin', 'unused', 'admin', 1),
        (2, 'int_viewer', 'unused', 'user', 1)");
    $pdo->exec("INSERT INTO user_api_keys (user_id, key_name, api_key, permissions) VALUES
        (1, 'admin write', 'INT_ADMIN_WRITE', 'write'),
        (1, 'admin read',  'INT_ADMIN_READ',  'read')");
    $pdo->prepare("INSERT OR REPLACE INTO settings (key, value) VALUES ('mcp_php_binary', ?)")
        ->execute([PHP_BINARY]);

    $pdo->exec("INSERT INTO domains (id, name, ssl_status) VALUES (7, 'track.int-test.example', 'installed')");
    $pdo->exec("INSERT INTO campaigns (id, name, alias, token, state, is_archived, domain_id) VALUES
        (42, 'Int Test Camp', 'intcamp', 'tok42xyz', 'active', 0, 7)");
    $pdo->exec("INSERT INTO app_configs (name, campaign_id, config_key, config_json, is_active) VALUES
        ('Stub A', 42, 'seedkey123', '{\"kind\":\"stub\",\"title\":\"Hello\"}', 1)");

    $socket = stream_socket_server('tcp://127.0.0.1:0', $errno, $error);
    if (!$socket) {
        throw new RuntimeException($error);
    }
    $address = stream_socket_get_name($socket, false);
    fclose($socket);
    $server = proc_open([PHP_BINARY, '-S', $address, '-t', $dir],
        [0 => ['pipe', 'r'], 1 => ['file', $dir . '/mcp-int-http.log', 'a'],
         2 => ['file', $dir . '/mcp-int-http.log', 'a']], $pipes, $dir);
    if (!is_resource($server)) {
        throw new RuntimeException('Could not start the MCP integration test server');
    }
    fclose($pipes[0]);
    $ready = false;
    for ($i = 0; $i < 50; $i++) {
        $probe = @file_get_contents("http://$address/mcp.php", false, stream_context_create(['http' => ['ignore_errors' => true]]));
        if (is_string($probe) && strpos($probe, 'send JSON-RPC') !== false) {
            $ready = true;
            break;
        }
        usleep(100000);
    }
    if (!$ready) {
        throw new RuntimeException('MCP test server did not start');
    }

    $rpc = static function (string $tool, array $args, string $key) use ($address): array {
        $raw = file_get_contents("http://$address/mcp.php?k=" . urlencode($key), false, stream_context_create(['http' => [
            'method' => 'POST',
            'header' => "Content-Type: application/json\r\n",
            'content' => json_encode(['jsonrpc' => '2.0', 'id' => 1, 'method' => 'tools/call',
                'params' => ['name' => $tool, 'arguments' => $args]]),
            'ignore_errors' => true,
            'timeout' => 20,
        ]]));
        $envelope = json_decode((string) $raw, true);
        $text = $envelope['result']['content'][0]['text'] ?? '';
        $decoded = json_decode($text, true);
        return [
            'isError' => (bool) ($envelope['result']['isError'] ?? false),
            'payload' => is_array($decoded) ? $decoded : $text,
        ];
    };

    // --- tools/list ------------------------------------------------------------
    $raw = file_get_contents("http://$address/mcp.php?k=INT_ADMIN_READ", false, stream_context_create(['http' => [
        'method' => 'POST', 'header' => "Content-Type: application/json\r\n",
        'content' => json_encode(['jsonrpc' => '2.0', 'id' => 1, 'method' => 'tools/list']),
        'ignore_errors' => true, 'timeout' => 20,
    ]]));
    $names = array_column(json_decode((string) $raw, true)['result']['tools'] ?? [], 'name');
    foreach (['orbitra_get_integration_code', 'orbitra_list_app_configs', 'orbitra_save_app_config', 'orbitra_telegram_status', 'orbitra_integrations_status'] as $tool) {
        check(in_array($tool, $names, true), "tools/list exposes $tool");
    }

    // --- get_integration_code: same code the panel would show -------------------
    $res = $rpc('orbitra_get_integration_code', ['campaign_id' => 42, 'method' => 'kclient_js'], 'INT_ADMIN_READ');
    debugDump('kclient_js', $res);
    $code = (string) ($res['payload']['data']['code'] ?? '');
    check(!$res['isError'] && strpos($code, 'https://track.int-test.example') !== false
        && strpos($code, 'tok42xyz') !== false,
        'kclient_js code uses the campaign https domain + token');

    $bb = $rpc('orbitra_get_integration_code', ['campaign_id' => 42, 'method' => 'back_button', 'options' => ['trap_url' => 'https://offer.net/lp']], 'INT_ADMIN_READ');
    debugDump('back_button', $bb);
    $bbCode = (string) ($bb['payload']['data']['code'] ?? '');
    check(!$bb['isError'] && strpos($bbCode, 'https://offer.net/lp?sub1=back_button') !== false
        && strpos($bbCode, 'popstate') !== false,
        'back_button code carries the tagged trap url and the popstate guard');

    $cd = $rpc('orbitra_get_integration_code', ['campaign_id' => 42, 'method' => 'countdown', 'options' => ['hours' => 2, 'theme' => 'fire', 'expire_action' => 'redirect']], 'INT_ADMIN_READ');
    debugDump('countdown', $cd);
    $cdCode = (string) ($cd['payload']['data']['code'] ?? '');
    check(!$cd['isError'] && strpos($cdCode, 'linear-gradient(135deg,#f97316 0%,#dc2626 100%)') !== false
        && strpos($cdCode, 'var totalSeconds = 7200;') !== false
        && strpos($cdCode, 'campaignId = \'42\'') !== false,
        'countdown code applies options (theme, duration, campaign id)');

    $miss = $rpc('orbitra_get_integration_code', ['campaign_id' => 42, 'method' => 'nope'], 'INT_ADMIN_READ');
    check($miss['isError'] && strpos((string) $miss['payload'], 'Unknown method') !== false,
        'unknown method is a named error listing valid methods');

    $noCamp = $rpc('orbitra_get_integration_code', ['campaign_id' => 999, 'method' => 'kclient_js'], 'INT_ADMIN_READ');
    check($noCamp['isError'] && strpos((string) $noCamp['payload'], 'Campaign not found') !== false,
        'missing campaign is a clean error');

    // --- app configs ------------------------------------------------------------
    $list = $rpc('orbitra_list_app_configs', [], 'INT_ADMIN_READ');
    $rows = is_array($list['payload']['data'] ?? null) ? $list['payload']['data'] : [];
    check(!$list['isError'] && count($rows) === 1 && ($rows[0]['config_key'] ?? '') === 'seedkey123',
        'orbitra_list_app_configs returns the seeded config with its key');

    $saved = $rpc('orbitra_save_app_config', ['name' => 'Minted by MCP', 'config_json' => ['kind' => 'banner', 'html' => '<b>hi</b>'], 'campaign_id' => 42], 'INT_ADMIN_WRITE');
    debugDump('save_app_config', $saved);
    $savedRow = $saved['payload']['data'] ?? [];
    check(!$saved['isError'] && !empty($savedRow['config_key']) && (int) ($savedRow['id'] ?? 0) > 0
        && strpos((string) ($savedRow['config_json'] ?? ''), '"kind":"banner"') !== false,
        'orbitra_save_app_config creates a config with a minted key and the payload');

    // The public endpoint the generated landings hit serves what MCP just saved.
    $pubRaw = @file_get_contents("http://$address/api.php?action=app_config&key=" . urlencode((string) ($savedRow['config_key'] ?? '')), false, stream_context_create(['http' => ['ignore_errors' => true]]));
    check(strpos((string) $pubRaw, '"kind":"banner"') !== false,
        'the saved config is served by the public app_config endpoint');

    $updated = $rpc('orbitra_save_app_config', ['id' => (int) ($savedRow['id'] ?? 0), 'name' => 'Minted by MCP', 'config_json' => ['kind' => 'stub'], 'is_active' => false], 'INT_ADMIN_WRITE');
    $updRow = $updated['payload']['data'] ?? [];
    check(!$updated['isError'] && (int) ($updRow['is_active'] ?? 1) === 0 && ($updRow['config_key'] ?? '') === ($savedRow['config_key'] ?? '?'),
        'orbitra_save_app_config updates by id and keeps the same key');

    $readKey = $rpc('orbitra_save_app_config', ['name' => 'x', 'config_json' => []], 'INT_ADMIN_READ');
    check($readKey['isError'] && strpos((string) $readKey['payload'], 'read-only') !== false,
        'orbitra_save_app_config is write-gated at the MCP layer');

    // --- status tools -------------------------------------------------------------
    $tg = $rpc('orbitra_telegram_status', [], 'INT_ADMIN_READ');
    check(!$tg['isError'] && array_key_exists('connected', $tg['payload']['data'] ?? []),
        'orbitra_telegram_status answers with the bot state');

    $st = $rpc('orbitra_integrations_status', [], 'INT_ADMIN_WRITE');
    debugDump('integrations_status', $st);
    $sections = $st['payload'] ?? [];
    check(!$st['isError'] && array_key_exists('cloudflare', $sections) && array_key_exists('telegram', $sections) && array_key_exists('traffic_sources', $sections),
        'orbitra_integrations_status aggregates cloudflare + telegram + traffic sources');
} finally {
    if (is_resource($server)) {
        proc_terminate($server);
        proc_close($server);
    }
    $pdo = null;
    $harness->stop();
}
exit($failures ? 1 : 0);
